    #[test]
    fn floor_clamps_legacy_codex_task_to_configured_claude_minimum() {
        // Legacy mode permits a Codex task tier while min_model remains a
        // Claude-only floor. The mandatory floor must win; provider-aware
        // advisory comparisons must not bypass it.
        let (model, effort) = apply_model_effort_floor(
            "gpt-5.6-terra",
            "medium",
            Some("claude-opus-4-7"),
            Some("high"),
        );
        assert_eq!(model, "claude-opus-4-7");
        assert_eq!(effort, "high");
    }

    #[test]
    fn floor_leaves_at_floor_unchanged() {
        let (m, e) = apply_model_effort_floor(
            "claude-opus-4-7",
            "high",
            Some("claude-opus-4-7"),
            Some("high"),
        );
        assert_eq!(m, "claude-opus-4-7");
        assert_eq!(e, "high");
    }

    #[test]
    fn floor_never_lowers_above_floor() {
        // Higher tier at lower effort is still above floor — must NOT be touched.
        let (m, e) = apply_model_effort_floor(
            "claude-opus-4-8",
            "medium",
            Some("claude-opus-4-7"),
            Some("high"),
        );
        assert_eq!(m, "claude-opus-4-8");
        assert_eq!(e, "medium");
    }

    #[test]
    fn floor_effort_tiebreak_same_model() {
        // #172: same model, effort below floor → effort bumped, model unchanged.
        let (m, e) = apply_model_effort_floor("claude-opus-4-7", "medium", None, Some("high"));
        assert_eq!(m, "claude-opus-4-7");
        assert_eq!(e, "high");
    }

    #[test]
    fn floor_none_is_identity() {
        // Regression guard: no floor → spawn values identical to today.
        let (m, e) = apply_model_effort_floor("claude-sonnet-5", "medium", None, None);
        assert_eq!(m, "claude-sonnet-5");
        assert_eq!(e, "medium");
    }

    #[test]
    fn floor_reviewer_floats_above_floored_worker() {
        // #172: a task asking for sonnet-5 with a floor of opus-47 spawns the worker
        // at opus-47, and the reviewer escalates strictly above it (opus-48).
        let (worker_model, _) = apply_model_effort_floor(
            "claude-sonnet-5",
            "high",
            Some("claude-opus-4-7"),
            Some("high"),
        );
        assert_eq!(worker_model, "claude-opus-4-7");
        let reviewer = escalated_reviewer_model(&worker_model, "claude-sonnet-5").unwrap();
        assert_eq!(reviewer, "claude-opus-4-8");
        assert!(model_rank(&reviewer) > model_rank(&worker_model));
    }

    fn make_dummy_slot() -> SlotState {
        use tokio::io::BufReader;

        let rt = tokio::runtime::Runtime::new().unwrap();
        let mut child = rt.block_on(async {
            tokio::process::Command::new("true")
                .stdin(std::process::Stdio::piped())
                .stdout(std::process::Stdio::piped())
                .spawn()
                .unwrap()
        });
        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();
        let reader = BufReader::new(stdout);
        let proc = runner::RunnerProc::Claude(agent::AgentProc::from_parts(child, stdin, reader));
        slot_with_process(proc)
    }

    fn slot_with_process(proc: runner::RunnerProc) -> SlotState {
        let now = std::time::Instant::now();
        SlotState {
            agent_name: "Test-1".into(),
            proc: SlotProcess::running(proc),
            task_id: 1,
            session_id: "sess".into(),
            model: "test-model".into(),
            effort: "high".into(),
            worktree_path: PathBuf::from("/tmp/test"),
            branch: "test-branch".into(),
            remote_branch: "test-branch".into(),
            draining: false,
            pending_watchdog_breach: None,
            pr: None,
            rework_count: 0,
            cost_tokens: 500,
            limit_tokens: 500,
            token_usage: runner::TokenUsage::default(),
            last_terminal_usage: runner::TokenUsage::default(),
            last_terminal_cost_usd: None,
            cost_usd: 0.01,
            task_started_at: now,
            turn_started_at: now,
            last_event_at: now,
            turn_ended_at: None,
            agent_state: None,
            session_log: None,
            live_stats: LiveStats::new(),
            error_turn_count: 0,
            last_error_text: None,
            agent_run_id: None,
            cap_run_id: None,
            r2_origin: false,
            reviewed_head_sha: None,
            continuation_id: None,
            pending_prompt: "test prompt".into(),
            pending_turn_kind: "initial".into(),
        }
    }

    #[tokio::test]
    async fn active_slot_check_drains_queued_events_before_liveness_for_both_roles() {
        use tokio::io::BufReader;

        for role in ["worker", "reviewer"] {
            let mut child = tokio::process::Command::new("sh")
                .args([
                    "-c",
                    r#"printf '%s\n' '{"type":"tool_use","name":"Bash","input":{"command":"true"}}'"#,
                ])
                .stdin(std::process::Stdio::piped())
                .stdout(std::process::Stdio::piped())
                .spawn()
                .unwrap();
            let stdin = child.stdin.take().unwrap();
            let stdout = child.stdout.take().unwrap();
            let proc = runner::RunnerProc::Claude(agent::AgentProc::from_parts(
                child,
                stdin,
                BufReader::new(stdout),
            ));
            let mut slot = slot_with_process(proc);
            slot.last_event_at = std::time::Instant::now() - std::time::Duration::from_secs(61);
            let tempdir = tempfile::tempdir().unwrap();
            let limits = CostLimits {
                max_idle_secs: Some(60),
                ..Default::default()
            };

            assert!(
                check_active_slot_limits(&mut slot, tempdir.path(), role, &limits)
                    .await
                    .unwrap()
                    .is_none()
            );
            assert!(
                slot.last_event_at.elapsed() < std::time::Duration::from_secs(60),
                "{role} queued event was not consumed before its liveness check"
            );
        }
    }

    #[tokio::test]
    async fn drain_events_bounds_noisy_slot_work_per_tick() {
        use tokio::io::BufReader;

        let command = format!(
            "i=0; while [ \"$i\" -lt {} ]; do printf '%s\\n' '{{\"type\":\"tool_use\",\"name\":\"Bash\",\"input\":{{\"command\":\"true\"}}}}'; i=$((i+1)); done",
            MAX_STREAM_LINES_PER_TICK + 1
        );
        let mut child = tokio::process::Command::new("sh")
            .args(["-c", &command])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .spawn()
            .unwrap();
        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();
        let proc = runner::RunnerProc::Claude(agent::AgentProc::from_parts(
            child,
            stdin,
            BufReader::new(stdout),
        ));
        let mut slot = slot_with_process(proc);
        let tempdir = tempfile::tempdir().unwrap();

        assert!(
            drain_events(&mut slot, tempdir.path(), "worker", &CostLimits::default())
                .await
                .unwrap()
                .is_none()
        );
        assert_eq!(slot.live_stats.tool_count, MAX_STREAM_LINES_PER_TICK as u32);
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn pre_authoritative_exit_finalization_folds_usage_beyond_drain_bound() {
        use tokio::io::BufReader;

        let command = format!(
            "i=0; while [ \"$i\" -lt {MAX_STREAM_LINES_PER_TICK} ]; do printf '%s\\n' '{{}}'; i=$((i+1)); done; printf '%s\\n' '{{\"type\":\"result\",\"result\":\"failed before signal\",\"is_error\":true,\"usage\":{{\"input_tokens\":100,\"cache_read_input_tokens\":80,\"cache_creation_input_tokens\":10,\"output_tokens\":5}}}}'; exit 1"
        );
        let mut child = tokio::process::Command::new("sh")
            .args(["-c", &command])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .spawn()
            .unwrap();
        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();
        let proc = runner::RunnerProc::Claude(agent::AgentProc::from_parts(
            child,
            stdin,
            BufReader::new(stdout),
        ));
        let mut slot = slot_with_process(proc);
        slot.cost_tokens = 0;
        slot.limit_tokens = 0;
        slot.cost_usd = 0.0;
        let db_dir = tempfile::tempdir().unwrap();
        let limits = CostLimits {
            max_task_tokens: Some(100),
            ..Default::default()
        };

        assert!(drain_events(
            &mut slot,
            &db_dir.path().join("q.db"),
            "worker",
            &CostLimits::default(),
        )
        .await
        .unwrap()
        .is_none());
        assert_eq!(slot.token_usage, runner::TokenUsage::default());
        tokio::time::timeout(std::time::Duration::from_secs(3), async {
            while slot.try_wait().unwrap().is_none() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("provider must exit without a managed signal");

        let diagnostic = slot
            .finalize_pre_authoritative_exit_evidence("worker", &limits)
            .await
            .expect("late active-owner terminal must emit a diagnostic");
        assert_eq!(
            slot.token_usage,
            runner::TokenUsage {
                input_tokens: 100,
                uncached_input_tokens: 20,
                cached_input_tokens: 80,
                cache_write_input_tokens: 10,
                output_tokens: 5,
                reasoning_tokens: 0,
            },
            "the evidence finalizer must fold usage before teardown drains the remaining pipe"
        );
        assert_eq!(diagnostic["role"], "worker");
        assert_eq!(diagnostic["raw_input_tokens"], 100);
        assert_eq!(diagnostic["uncached_input_tokens"], 20);
        assert_eq!(diagnostic["cached_input_tokens"], 80);
        assert_eq!(diagnostic["cache_write_input_tokens"], 10);
        assert_eq!(diagnostic["output_tokens"], 5);
        assert_eq!(diagnostic["reasoning_tokens"], 0);
        assert_eq!(diagnostic["raw_total_tokens"], 105);
        assert_eq!(diagnostic["uncached_total_tokens"], 25);
        assert_eq!(diagnostic["cumulative_raw_total_tokens"], 105);
        assert_eq!(diagnostic["cumulative_uncached_total_tokens"], 25);
        assert_eq!(diagnostic["cumulative_limit_tokens"], 105);
        assert_eq!(diagnostic["configured_limit_basis"], "raw");
        assert_eq!(diagnostic["configured_max_task_tokens"], 100);
        assert_eq!(diagnostic["cost_usd"], serde_json::Value::Null);
        assert_eq!(diagnostic["breach"], true);
        assert_eq!(diagnostic["action"], "active_owner_watchdog_termination");

        let expected = slot.token_usage;
        let terminal = slot.kill_and_reap().await;
        let mut after_teardown = expected;
        capture_terminal_usage(runner::AgentKind::Claude, &terminal, &mut after_teardown);
        assert_eq!(
            after_teardown, expected,
            "the consumed terminal record must not be duplicated by final reap"
        );
    }

