    #[test]
    fn r2_sampling_retains_an_earlier_head_decision_after_rework() {
        let dir = tempfile::tempdir().unwrap();
        let mut conn = quorum_core::db::open(&dir.path().join("q.db")).unwrap();
        let task_id = tasks::create(
            &mut conn,
            "creator",
            "sampled task",
            None,
            0,
            None,
            None,
            None,
            None,
            100,
        )
        .unwrap();
        quorum_core::review_audits::record_r2_requirement(&mut conn, task_id, 42, "head-a", true)
            .unwrap();
        let policy = R2SamplingPolicy {
            enabled: true,
            target_per_stratum: 0,
            steady_state_p: 0.0,
            default_model: "model".into(),
            default_effort: "high".into(),
        };

        assert!(!decide_r2_requirement(&mut conn, task_id, 42, "head-b", &policy,).unwrap());
        assert!(
            r2_required_for_head(&conn, task_id, 42, "head-a"),
            "a newer skipped head must not overwrite a prior required R2"
        );
        assert!(
            !r2_required_for_head(&conn, task_id, 42, "head-b"),
            "the rework head keeps its independently sampled skip"
        );
        quorum_core::approvals::record(
            &mut conn,
            &quorum_core::approvals::Approval {
                pr_number: 42,
                review_role: "r1".into(),
                task_id,
                author: "worker".into(),
                reviewer: "rev1".into(),
                verdict: "approved".into(),
                blocking_count: 0,
                approved_head_sha: "head-a".into(),
            },
        )
        .unwrap();
        assert_eq!(
            next_needed_role(&conn, 42, "head-a").unwrap(),
            Some("r2"),
            "force-pushing the prior required head back must still require R2"
        );
    }

    #[test]
    fn exhausted_rework_budget_preserves_required_r2_for_returned_head() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("q.db");
        let mut conn = quorum_core::db::open(&db_path).unwrap();
        let task_id = tasks::create(
            &mut conn,
            "creator",
            "sampled task",
            None,
            0,
            None,
            None,
            None,
            None,
            100,
        )
        .unwrap();
        let policy = R2SamplingPolicy {
            enabled: true,
            target_per_stratum: 0,
            steady_state_p: 0.0,
            default_model: "model".into(),
            default_effort: "high".into(),
        };

        // Head A was reviewed before rework exhausted the budget and durably
        // required R2. Rework then consumes the final bounded round.
        quorum_core::review_audits::record_r2_requirement(&mut conn, task_id, 42, "head-a", true)
            .unwrap();
        conn.execute(
            "UPDATE tasks SET rework_round=?1 WHERE id=?2",
            rusqlite::params![quorum_core::lifecycle::REWORK_CAP as i64, task_id],
        )
        .unwrap();

        // The branch moves to new head B, which correctly receives the final
        // round's recorded skip. It then force-pushes back to A and obtains a
        // fresh R1 approval. The cap can establish a skip only for B; it
        // cannot replace A's R2 gate.
        assert!(!decide_r2_requirement(&mut conn, task_id, 42, "head-b", &policy).unwrap());
        assert!(decide_r2_requirement(&mut conn, task_id, 42, "head-a", &policy).unwrap());
        quorum_core::approvals::record(
            &mut conn,
            &quorum_core::approvals::Approval {
                pr_number: 42,
                review_role: "r1".into(),
                task_id,
                author: "worker".into(),
                reviewer: "fresh-r1".into(),
                verdict: "approved".into(),
                blocking_count: 0,
                approved_head_sha: "head-a".into(),
            },
        )
        .unwrap();
        assert_eq!(next_needed_role(&conn, 42, "head-a").unwrap(), Some("r2"));

        // Restart reconciliation reads the same immutable decision.
        drop(conn);
        let conn = quorum_core::db::open(&db_path).unwrap();
        assert!(r2_required_for_head(&conn, task_id, 42, "head-a"));
        assert_eq!(next_needed_role(&conn, 42, "head-a").unwrap(), Some("r2"));
    }

    /// A sampled-out head leaves no `r2` approval row. The provisioning
    /// decision must read that as "complete, awaiting merge", never as
    /// exhaustion — the latter parks a fully-approved task forever.
    #[test]
    fn sampled_r2_skip_reports_all_approved_not_exhausted() {
        let dir = tempfile::tempdir().unwrap();
        let mut conn = quorum_core::db::open(&dir.path().join("q.db")).unwrap();
        let task_id = tasks::create(
            &mut conn,
            "creator",
            "sampled skip merge-wait",
            None,
            0,
            None,
            None,
            None,
            None,
            100,
        )
        .unwrap();
        quorum_core::review_audits::record_r2_requirement(&mut conn, task_id, 77, "head-x", false)
            .unwrap();
        quorum_core::approvals::record(
            &mut conn,
            &quorum_core::approvals::Approval {
                pr_number: 77,
                review_role: "r1".into(),
                task_id,
                author: "worker".into(),
                reviewer: "rev1".into(),
                verdict: "approved".into(),
                blocking_count: 0,
                approved_head_sha: "head-x".into(),
            },
        )
        .unwrap();

        assert_eq!(
            decide_provision(&conn, task_id, 77, "head-x").unwrap(),
            ProvisionDecision::AllApproved,
            "an R1-only approval for a sampled-out head is complete, not exhausted"
        );
        assert!(
            all_required_roles_approved(&conn, 77, "head-x").unwrap(),
            "merge-wait recovery must treat a sampled skip as fully approved"
        );
    }

    #[test]
    fn r2_handoff_provision_outcomes_keep_reservation_misses_and_errors_distinct() {
        let attached: Result<ReviewerProvisionOutcome> = Ok(ReviewerProvisionOutcome::Attached);
        assert_eq!(
            r2_provision_disposition(true, &attached),
            R2ProvisionDisposition::Attached,
            "an attached reviewer transfers R2 authority"
        );
        assert_eq!(
            r2_provision_disposition(true, &attached).end_reason(),
            "r2-pending"
        );

        let reservation_miss: Result<ReviewerProvisionOutcome> =
            Ok(ReviewerProvisionOutcome::Unavailable);
        assert_eq!(
            r2_provision_disposition(false, &reservation_miss),
            R2ProvisionDisposition::Unavailable,
            "a reservation miss attaches no reviewer but remains retriable"
        );
        assert_eq!(
            r2_provision_disposition(false, &reservation_miss).end_reason(),
            "r2-provision-unavailable"
        );

        let spawn_failure: Result<ReviewerProvisionOutcome> = Ok(ReviewerProvisionOutcome::Failed(
            "R2: failed to spawn reviewer: authentication failed".into(),
        ));
        assert_eq!(
            r2_provision_disposition(false, &spawn_failure),
            R2ProvisionDisposition::Error,
            "a real reviewer spawn failure must not share the reservation-miss bucket"
        );
        assert_eq!(
            r2_provision_disposition(false, &spawn_failure).end_reason(),
            "r2-spawn-error"
        );
        assert_eq!(
            match spawn_failure.as_ref().unwrap() {
                ReviewerProvisionOutcome::Failed(reason) => reason,
                _ => unreachable!("fixture is a real provisioning failure"),
            },
            "R2: failed to spawn reviewer: authentication failed",
            "the production spawn cleanup returns this reason to the R2 handoff"
        );

        let provision_error: Result<ReviewerProvisionOutcome> = Err(QuorumError::Io(
            "provider launch authentication failed".into(),
        ));
        assert_eq!(
            r2_provision_disposition(false, &provision_error),
            R2ProvisionDisposition::Error,
            "a provisioning error must not be mistaken for a reservation miss"
        );
        assert_eq!(
            r2_provision_disposition(false, &provision_error).end_reason(),
            "r2-spawn-error"
        );
        assert_eq!(
            provision_error.as_ref().unwrap_err().to_string(),
            "io: provider launch authentication failed",
            "the handoff logs this unmodified provisioning error"
        );
        assert_eq!(
            r2_provision_disposition(true, &provision_error),
            R2ProvisionDisposition::Attached,
            "a live R2 keeps transferred-review authority even if reservation release errors"
        );
    }

